type Scope={tenant:string;property:string;reservation:string;actor:string};
function amount(v:unknown):bigint{if(typeof v!=='string'||!/^(0|[1-9][0-9]{0,11})$/.test(v))throw Error('Invalid opening amount.');return BigInt(v);}
export function readOpeningReview(value:unknown,scope:Scope){
 const r=value as Record<string,unknown>;if(!r||r.schema_version!==1||r.tenant_id!==scope.tenant||r.property_id!==scope.property||r.reservation_id!==scope.reservation||r.actor_id!==scope.actor||r.currency!=='USD'||r.complete!==true||!Array.isArray(r.lines)||!r.lines.length||r.lines.length>1000||!Array.isArray(r.reversals)||r.reversals.length>1000)throw Error('Opening review scope changed.');
 const keys=new Set<string>(),used=new Map<string,bigint>();
 const lines=r.lines.map(value=>{const l=value as Record<string,unknown>;if(!l||typeof l.source_key!=='string'||!l.source_key.startsWith('opening:')||keys.has(l.source_key)||typeof l.description!=='string'||!l.description.trim()||l.description.length>500)throw Error('Invalid opening category.');keys.add(l.source_key);const original=amount(l.original_minor),itemized=amount(l.itemized_minor),available=amount(l.available_minor);if(original-itemized!==available)throw Error('Opening amounts do not reconcile.');return {source_key:l.source_key,description:l.description,original_minor:original.toString(),itemized_minor:itemized.toString(),available_minor:available.toString()};});
 const ids=new Set<string>();const reversals=r.reversals.map(value=>{const e=value as Record<string,unknown>;if(!e||typeof e.reversal_id!=='string'||!/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(e.reversal_id)||ids.has(e.reversal_id)||typeof e.reference!=='string'||!e.reference.trim()||e.reference.length>200||typeof e.itemized!=='boolean')throw Error('Invalid opening reversal.');ids.add(e.reversal_id);const total=amount(e.amount_minor);if(total===BigInt(0))throw Error('Invalid reversal total.');if(!e.itemized&&e.itemized_lines!==null)throw Error('Unexpected reversal itemization.');if(e.itemized){if(!Array.isArray(e.itemized_lines)||!e.itemized_lines.length||e.itemized_lines.length>100)throw Error('Missing reversal itemization.');let sum=BigInt(0);const seen=new Set<string>();for(const v of e.itemized_lines){const l=v as Record<string,unknown>;if(!l||typeof l.source_key!=='string'||!keys.has(l.source_key)||seen.has(l.source_key))throw Error('Invalid reversal category.');seen.add(l.source_key);const n=amount(l.amount_minor);if(n===BigInt(0))throw Error('Invalid itemized amount.');sum+=n;used.set(l.source_key,(used.get(l.source_key)||BigInt(0))+n);}if(sum!==total)throw Error('Reversal itemization does not reconcile.');}const revision=e.classification_revision===undefined||e.classification_revision===null?null:amount(e.classification_revision).toString();if(!e.itemized&&revision!==null)throw Error("Unexpected classification revision.");return {id:e.reversal_id,reference:e.reference,amount_minor:total.toString(),itemized:e.itemized,classification_revision:revision,itemized_lines:e.itemized?(e.itemized_lines as {source_key:string;amount_minor:string}[]).map(l=>({source_key:l.source_key,amount_minor:l.amount_minor})):[]};});
 for(const line of lines)if((used.get(line.source_key)||BigInt(0)).toString()!==line.itemized_minor)throw Error('Opening category totals do not reconcile.');
 return {lines,reversals};
}
